package vn.svframe.svframemmo.skill.list;
import net.minecraft.entity.LivingEntity;import net.minecraft.particle.ParticleTypes;import net.minecraft.server.world.ServerWorld;import net.minecraft.sound.SoundCategory;import net.minecraft.sound.SoundEvents;import vn.svframe.svframelib.SVFrameLib;import vn.svframe.svframelib.api.event.PlayerAttackEvent;import vn.svframe.svframelib.damage.DamageType;import vn.svframe.svframelib.skill.SkillMetadata;import vn.svframe.svframelib.skill.handler.*;import vn.svframe.svframelib.skill.result.def.SimpleSkillResult;import vn.svframe.svframelib.util.configobject.ConfigObject;import vn.svframe.svframemmo.SVFrameMMO;
@BuiltinSkillHandler(mods={"extra"},triggerable=false) public final class Sneaky_Picky extends SkillHandler<SimpleSkillResult>{private static boolean hook;public Sneaky_Picky(ConfigObject c){super(c);install();}private static synchronized void install(){if(hook)return;hook=true;PlayerAttackEvent.EVENT.register(e->{var d=SVFrameMMO.playerData().get(e.getPlayer());if(!e.getAttack().getDamage().hasType(DamageType.WEAPON)||d.isInCombat())return;var h=SVFrameLib.inst().getSkills().getHandler("SNEAKY_PICKY");if(h==null)return;var passive=e.getData().getPassiveSkillMap().getSkill(h);if(passive!=null)passive.getTriggeredSkill().cast(SkillMetadata.of(e));});}public SimpleSkillResult getResult(SkillMetadata m){return new SimpleSkillResult(m.hasAttackSource()&&m.getTargetLivingEntityOrNull()!=null);}public void whenCast(SimpleSkillResult r,SkillMetadata m){if(!r.isSuccessful())return;LivingEntity t=m.getTargetLivingEntityOrNull();m.getAttackSource().getDamage().multiplicativeModifier(1+m.getParameter("extra")/100d,DamageType.WEAPON);if(t.getWorld() instanceof ServerWorld w){w.spawnParticles(ParticleTypes.SMOKE,t.getX(),t.getBodyY(.5),t.getZ(),64,0,0,0,.05);w.playSound(null,t.getBlockPos(),SoundEvents.ENTITY_ZOMBIE_ATTACK_IRON_DOOR,SoundCategory.PLAYERS,1,2);}}}
